#!/usr/bin/env node
// =============================================================================
// Plugin manifest-index generator — E11 (2026-06-08)
// =============================================================================
//
// Regenerates plugins/index.json from the *.manifest.json files on disk, and
// validates EACH manifest against plugins/schemas/plugin-manifest.json before
// emitting. Browsers cannot directory-walk, so loader.js#fetchManifestIndex
// discovers plugins through this index. Hand-maintaining ~40 descriptors is
// drift-prone (the previous `$comment` already claimed "25 plugins" when the
// list held 36); this script makes the index a build artifact instead.
//
// Run with /usr/bin/node from apps/holtburger-web:
//
//   node plugins/gen-index.mjs            # rewrite plugins/index.json
//   node plugins/gen-index.mjs --check    # exit 1 if index.json is stale
//   node plugins/gen-index.mjs --stdout   # print to stdout, don't write
//
// `--check` is a ready-made staleness gate but is not auto-invoked (this app has
// no package.json / JS test job — same as scripts/gen-modulepreload.mjs). Run it
// (and test_plugin_index_gen.mjs) by hand pre-commit, or wire into CI later.
//
// Design constraints (per E11 SAFE / dependency-light):
//   - Zero new dependencies. The web app vendors no JSON-Schema validator
//     (it has no package.json), so we read schemas/plugin-manifest.json and
//     run a *minimal structural validator* (required / type / enum / pattern /
//     minLength / uniqueItems / nested items+properties) against it. This is a
//     subset of JSON-Schema draft 2020-12 — enough for the manifest schema —
//     deliberately not a general-purpose validator.
//   - Deterministic output: descriptors are stable-sorted by manifest `id`
//     (tie-broken by `name`, then filename), and the file is byte-stable across
//     runs (2-space JSON + trailing newline, matching the existing index.json).
//
// The descriptor shape mirrors what fetchManifestIndex consumes
// (loader.js:680-762): `{ manifestPath, devPath? }`. `devPath` points at the
// optional dev-override sidecar (`<id>.manifest.dev.json`), probed only in dev
// mode; it need not exist on disk. We keep emitting it for every descriptor to
// preserve byte-parity with the hand-written index.
//
// We intentionally do NOT emit a descriptor-level `entry` override. The loader
// reads `desc.entry` first, falling back to `manifest.entry` (loader.js:755-757);
// every manifest declares its own `entry` and the old hand index carried zero
// descriptor `entry` fields, so omitting it loses no addressing info. A plugin
// needing a custom entry sets it in its manifest, not the index.
//
// =============================================================================

import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, basename } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PLUGINS_DIR = __dirname;
const SCHEMA_PATH = join(PLUGINS_DIR, "schemas", "plugin-manifest.json");
const INDEX_PATH = join(PLUGINS_DIR, "index.json");

// The leading note on the generated index. Kept short + truthful — it points a
// reader at this generator instead of inviting hand-edits. The plugin count is
// templated so it can never go stale the way the old hand-written one did.
function indexComment(count) {
  return (
    `GENERATED by plugins/gen-index.mjs (E11). Do NOT hand-edit — run ` +
    `\`node plugins/gen-index.mjs\` to regenerate. Manifest index for ` +
    `plugins/loader.js#fetchManifestIndex(). Browsers cannot directory-walk; ` +
    `this index is how the loader discovers which plugins to consider. Each ` +
    `descriptor \`{manifestPath, devPath?}\` lets the loader fetch the ` +
    `per-plugin manifest, then the ESM entry (from manifest.entry), then ` +
    `optionally a manifest.dev.json sidecar. Adding a plugin = drop a ` +
    `{id}.manifest.json next to its {id}.js entry and rerun this script. ` +
    `${count} plugins are listed (every plugins/*.manifest.json on disk, ` +
    `each validated against schemas/plugin-manifest.json).`
  );
}

// =============================================================================
// [1] Minimal structural JSON-Schema validator
// =============================================================================
//
// Supports the subset the manifest schema uses: type, required, properties,
// items, enum, pattern, minLength, uniqueItems, additionalProperties:false.
// Collects ALL errors (never throws) — same contract as loader.js
// validateManifest (loader.js:101-209), but driven off the schema file so it
// tracks future schema edits automatically.

const JS_TYPE = (v) => {
  if (v === null) return "null";
  if (Array.isArray(v)) return "array";
  return typeof v; // "string" | "number" | "boolean" | "object"
};

function typeMatches(value, schemaType) {
  const types = Array.isArray(schemaType) ? schemaType : [schemaType];
  const actual = JS_TYPE(value);
  return types.some((t) => {
    if (t === "integer") return actual === "number" && Number.isInteger(value);
    if (t === "number") return actual === "number";
    return actual === t;
  });
}

/**
 * Validate `value` against `schema`. Returns a list of error strings (empty =
 * valid). `path` is a dotted breadcrumb for messages.
 *
 * @param {unknown} value
 * @param {Record<string, any>} schema
 * @param {string} [path]
 * @returns {string[]}
 */
function validateAgainstSchema(value, schema, path = "") {
  const errors = [];
  const at = path || "(root)";

  if (schema.type != null && !typeMatches(value, schema.type)) {
    errors.push(`${at}: expected type ${JSON.stringify(schema.type)}, got ${JS_TYPE(value)}`);
    // Type mismatch invalidates deeper checks; bail on this node.
    return errors;
  }

  if (schema.enum != null && !schema.enum.some((e) => e === value)) {
    errors.push(`${at}: must be one of ${JSON.stringify(schema.enum)} (got ${JSON.stringify(value)})`);
  }

  if (typeof value === "string") {
    if (schema.minLength != null && value.length < schema.minLength) {
      errors.push(`${at}: must be at least ${schema.minLength} char(s)`);
    }
    if (schema.pattern != null && !new RegExp(schema.pattern).test(value)) {
      errors.push(`${at}: must match /${schema.pattern}/ (got ${JSON.stringify(value)})`);
    }
  }

  if (Array.isArray(value)) {
    if (schema.uniqueItems === true) {
      const seen = new Set();
      for (const item of value) {
        const key = JSON.stringify(item);
        if (seen.has(key)) errors.push(`${at}: items must be unique (dup ${key})`);
        seen.add(key);
      }
    }
    if (schema.items != null) {
      value.forEach((item, i) => {
        errors.push(...validateAgainstSchema(item, schema.items, `${at}[${i}]`));
      });
    }
  }

  if (JS_TYPE(value) === "object") {
    const props = schema.properties || {};
    if (Array.isArray(schema.required)) {
      for (const key of schema.required) {
        if (!(key in value)) errors.push(`${at}: missing required key "${key}"`);
      }
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!(key in props)) errors.push(`${at}: unexpected key "${key}"`);
      }
    }
    for (const [key, sub] of Object.entries(props)) {
      if (key in value) {
        const child = path ? `${path}.${key}` : key;
        errors.push(...validateAgainstSchema(value[key], sub, child));
      }
    }
  }

  return errors;
}

// =============================================================================
// [2] Scan + validate + build descriptors
// =============================================================================

/**
 * @returns {{
 *   descriptors: {manifestPath:string,devPath:string}[],
 *   results: {file:string,id:string|null,name:string|null,errors:string[]}[],
 *   schema: Record<string, any>,
 * }}
 */
function build() {
  const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf8"));

  const files = readdirSync(PLUGINS_DIR)
    .filter((f) => f.endsWith(".manifest.json"))
    .sort(); // deterministic scan order regardless of FS enumeration order

  const results = [];
  for (const file of files) {
    const full = join(PLUGINS_DIR, file);
    let manifest = null;
    let parsed = false;
    let errors = [];
    try {
      manifest = JSON.parse(readFileSync(full, "utf8"));
      parsed = true;
    } catch (e) {
      errors.push(`invalid JSON: ${e.message}`);
    }
    const warnings = [];
    if (parsed) {
      // Always validate a successfully-parsed manifest — including one that
      // parses to JSON `null` or a non-object (a file literally containing
      // `null`/`42`/`[]`). The validator reports `expected type object, got …`
      // for those, so the schema's required-keys contract still bites and a
      // junk manifest can never slip into the index as a phantom descriptor.
      errors = validateAgainstSchema(manifest, schema);
      // Advisory cross-check: manifest `id` usually matches the filename stem,
      // but this is a CONVENTION, not a schema rule, and the loader discovers
      // by `manifestPath` (not `id`) — so a mismatch does NOT break loading and
      // must NOT block indexing (e.g. examine-target.manifest.json legitimately
      // carries id "examine-target-watcher"). Surface it as a warning only.
      // Guarded by the typeof check so a null/non-object manifest (already an
      // error above) doesn't throw here.
      const stem = basename(file, ".manifest.json");
      if (manifest != null && typeof manifest.id === "string" && manifest.id !== stem) {
        warnings.push(
          `id "${manifest.id}" differs from filename stem "${stem}" ` +
          `(allowed — loader resolves by path; flagged for navigability)`,
        );
      }
    }
    results.push({
      file,
      id: manifest && typeof manifest.id === "string" ? manifest.id : null,
      name: manifest && typeof manifest.name === "string" ? manifest.name : null,
      errors,
      warnings,
    });
  }

  // Stable sort by id, tie-break name, then filename. Falls back to filename
  // when a manifest failed to parse (id == null) so output stays deterministic.
  //
  // Compare by Unicode CODE POINT, not String.prototype.localeCompare():
  // localeCompare is ICU/locale-sensitive, so the collation of punctuation
  // ('-', '.') vs letters can reorder ids across different Node ICU builds or
  // LANG settings, silently producing a different byte output than the committed
  // index.json (which `--check` would then flag as stale on another host). A raw
  // code-point compare is host-independent, guaranteeing byte-identical output
  // everywhere. No ordering change on the current id set (verified by --check).
  const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0);
  const ok = results.filter((r) => r.errors.length === 0);
  ok.sort((a, b) => {
    const byId = cmp(a.id || a.file, b.id || b.file);
    if (byId !== 0) return byId;
    const byName = cmp(a.name || "", b.name || "");
    if (byName !== 0) return byName;
    return cmp(a.file, b.file);
  });

  const descriptors = ok.map((r) => {
    const stem = basename(r.file, ".manifest.json");
    return {
      manifestPath: `./${r.file}`,
      devPath: `./${stem}.manifest.dev.json`,
    };
  });

  return { descriptors, results, schema };
}

/**
 * Serialize the index deterministically. Matches the existing index.json house
 * style: 2-space indent, but each descriptor on ONE line (compact object) so
 * the file stays scannable and diffs stay one-line-per-plugin. Trailing newline.
 */
function serializeIndex(descriptors) {
  const lines = [];
  lines.push("{");
  // JSON.stringify on the comment string handles escaping (it contains
  // backticks + quotes) deterministically.
  lines.push(`  "$comment": ${JSON.stringify(indexComment(descriptors.length))},`);
  lines.push(`  "plugins": [`);
  descriptors.forEach((d, i) => {
    const comma = i < descriptors.length - 1 ? "," : "";
    // Compact one-line descriptor, keys in stable insertion order.
    const body = Object.entries(d)
      .map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`)
      .join(", ");
    lines.push(`    { ${body} }${comma}`);
  });
  lines.push(`  ]`);
  lines.push("}");
  return lines.join("\n") + "\n";
}

// =============================================================================
// [3] CLI
// =============================================================================

export { validateAgainstSchema, build, serializeIndex };

function main(argv) {
  const check = argv.includes("--check");
  const toStdout = argv.includes("--stdout");

  const { descriptors, results } = build();

  const failed = results.filter((r) => r.errors.length > 0);
  for (const r of results) {
    if (r.errors.length === 0) {
      console.error(`  ok   ${r.file}${r.id ? ` (${r.id})` : ""}`);
    } else {
      console.error(`  FAIL ${r.file}`);
      for (const e of r.errors) console.error(`         - ${e}`);
    }
    for (const w of r.warnings || []) console.error(`         ! ${w}`);
  }
  console.error(
    `\n${results.length - failed.length}/${results.length} manifests valid; ` +
    `${descriptors.length} indexed.`,
  );

  if (failed.length > 0) {
    console.error(`\nERROR: ${failed.length} manifest(s) failed schema validation; index NOT written.`);
    process.exit(1);
  }

  const generated = serializeIndex(descriptors);

  if (toStdout) {
    process.stdout.write(generated);
    return;
  }

  if (check) {
    let existing = "";
    try {
      existing = readFileSync(INDEX_PATH, "utf8");
    } catch {
      // missing → treat as stale.
    }
    if (existing !== generated) {
      console.error(
        `\nERROR: ${INDEX_PATH} is STALE. Run \`node plugins/gen-index.mjs\` and commit the result.`,
      );
      process.exit(1);
    }
    console.error(`\nindex.json is up to date.`);
    return;
  }

  writeFileSync(INDEX_PATH, generated);
  console.error(`\nWrote ${INDEX_PATH} (${descriptors.length} descriptors).`);
}

// Run only when invoked directly (not when imported by the test).
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main(process.argv.slice(2));
}
